CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, instructions text NOT NULL DEFAULT '');
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE vms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces, name text NOT NULL, last_seen_at timestamptz, control_state text NOT NULL DEFAULT 'agent' CHECK(control_state IN ('agent','user','switching','unknown')), UNIQUE(workspace_id,id));
CREATE TABLE credentials(token_hash text PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, role text NOT NULL CHECK(role IN ('client','vm')), vm_id uuid, revoked_at timestamptz, FOREIGN KEY(workspace_id,vm_id) REFERENCES vms(workspace_id,id), CHECK((role='vm')=(vm_id IS NOT NULL)));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, conversation_id uuid NOT NULL, objective text NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','waiting','pausing','paused','cancelling','cancelled','succeeded','failed','unknown')), reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE UNIQUE INDEX task_active ON tasks(conversation_id) WHERE state NOT IN ('cancelled','succeeded','failed');
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, conversation_id uuid NOT NULL, task_id uuid, role text NOT NULL CHECK(role IN ('user','assistant','system')), content text NOT NULL, sequence bigint GENERATED ALWAYS AS IDENTITY, client_message_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(conversation_id,client_message_id), FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, task_id uuid NOT NULL, vm_id uuid NOT NULL, state text NOT NULL DEFAULT 'running', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id), FOREIGN KEY(workspace_id,vm_id) REFERENCES vms(workspace_id,id));
CREATE UNIQUE INDEX run_vm_active ON runs(vm_id) WHERE state NOT IN ('cancelled','succeeded','failed');
CREATE UNIQUE INDEX run_task_active ON runs(task_id) WHERE state NOT IN ('cancelled','succeeded','failed');
CREATE TABLE commands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, vm_id uuid NOT NULL, task_id uuid, run_id uuid, kind text NOT NULL CHECK(kind IN ('stop','takeover','return_control')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','failed')), detail text, created_at timestamptz NOT NULL DEFAULT now(), acked_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,vm_id) REFERENCES vms(workspace_id,id), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE UNIQUE INDEX command_control_pending ON commands(vm_id) WHERE status='pending' AND kind IN ('takeover','return_control');
CREATE UNIQUE INDEX command_stop_pending ON commands(task_id) WHERE status='pending' AND kind='stop';
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces, vm_id uuid, event_id uuid UNIQUE, kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,vm_id) REFERENCES vms(workspace_id,id));
CREATE TABLE outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, event_id uuid NOT NULL REFERENCES events, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE input_receipts(workspace_id uuid NOT NULL, run_id uuid NOT NULL, message_id uuid NOT NULL, PRIMARY KEY(run_id,message_id), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id), FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id));
CREATE TABLE schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, conversation_id uuid NOT NULL, objective text NOT NULL, due_at timestamptz NOT NULL, timezone text NOT NULL, client_schedule_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE(workspace_id,client_schedule_id), FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE TABLE memories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces, text text NOT NULL, source_message_id uuid, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,source_message_id) REFERENCES messages(workspace_id,id));
CREATE TABLE memory_suppressions(workspace_id uuid NOT NULL, source_message_id uuid NOT NULL, PRIMARY KEY(workspace_id,source_message_id), FOREIGN KEY(workspace_id,source_message_id) REFERENCES messages(workspace_id,id));
